#include <bits/stdc++.h>
using namespace std;

#define int long long
#define ll long long
#define ii pair<int,int>
#define iii tuple<int,int,int>
#define fi first
#define se second
#define endl '\n'
#define debug(x) cout << #x << ": " << x << endl

#define pub push_back
#define pob pop_back
#define puf push_front
#define pof pop_front
#define lb lower_bound
#define ub upper_bound

#define rep(x,start,end) for(int x=(start)-((start)>(end));x!=(end)-((start)>(end));((start)<(end)?x++:x--))
#define all(x) (x).begin(),(x).end()
#define sz(x) (int)(x).size()

mt19937 rng(chrono::system_clock::now().time_since_epoch().count());

int n;
ii arr[200005];
vector<int> w[105];

ii pp[200005]; //reconstruct stuff from this
signed dp[200005][100]; //dont care about weight 100!
double val[200005];

signed main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	cin.exceptions(ios::badbit | ios::failbit);

	cin>>n;
	rep(x,1,n+1) cin>>arr[x].fi>>arr[x].se;
	rep(x,1,n+1) w[arr[x].fi].pub(arr[x].se);

	rep(x,1,100){
		sort(all(w[x]));
		reverse(all(w[x]));
	}

	double ans=0;

	int sum=0;
	for (auto it:w[100]) sum+=it;

	val[0]=1;
	rep(x,0,200005) if (val[x]!=0){
		if (x){
			rep(y,1,100) dp[x][y]=dp[pp[x].fi][y];
			dp[x][pp[x].se]++;
		}

		rep(y,1,100){
			if (dp[x][y]==sz(w[y])) continue;
			if (x+w[y][dp[x][y]]>=200005) continue;

			int x2=x+w[y][dp[x][y]];

			double v=val[x];
			v*=(double)y/100;

			if (val[x2]<v){
				val[x2]=v;
				pp[x2]={x,y};
			}
		}

		ans=max(ans,val[x]*(x+sum));
	}

	cout<<fixed<<setprecision(12)<<ans<<endl;
}

