#include <bits/stdc++.h>
using namespace std;
const int MAXN = 500005;
long long dp[MAXN]; vector<int> G[MAXN];
long long ans = 0;
void dfs(int u, int f) {
	int d = 0; for (int v : G[u]) if (v != f) dfs(v, u), d++;
	dp[u] = 0; for (int v : G[u]) if (v != f) dp[u] += max((u == f ? 0ll : 1ll), dp[v] - (d - 1));
	ans += 1ll * d * (d - 1) / 2;
}
int main() {
	int t; scanf("%d", &t); while (t--) {
		int n; scanf("%d", &n);
		for (int i = 1; i <= n; i++) G[i].clear();
		for (int i = 1; i < n; i++) {
			int u, v; scanf("%d %d", &u, &v);
			G[u].push_back(v); G[v].push_back(u);
		}
		int rt = 1; for (int i = 2; i <= n; i++) if (G[i].size() > G[rt].size()) rt = i;
		ans = 0; dfs(rt, rt);
		printf("%lld\n", ans + (dp[rt] + 1) / 2);
	}	
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define pb push_back
#define sort(nums) sort(begin(nums), end(nums))
typedef vector<ll> vll;
int ret;
bool can(int mid,vll& a,int k){
    int cnt=0,tot=0;
    for(int i=0;i<a.size();i++){
        if(a[i]<mid){
            cnt+=a[i]+1;
            tot+=a[i];
        }
        else{
            cnt+=min(mid,k-tot);
            tot+=mid;
        }
        if(tot>=k){
            ret=min(ret,cnt);
            return true;
        }
    }
    return false;
}
int main() {
    int t;
    cin>>t;
    while(t--){
        int n,k;
        cin>>n>>k;
        vll a(n);
        for(int i=0;i<n;i++){
            cin>>a[i];
        }
        ret=INT_MAX;
        sort(a);
        int l=0,r=a[n-1];
        while(l<=r){
            int mid=l+(r-l)/2;
            if(can(mid,a,k)){
                r=mid-1;
            }
            else{
                l=mid+1;
            }
        }
        cout<<ret<<endl;
    }
    return 0;
}

